// qrysmExport is the export qrysm's validator wrote, generated by vectorgen.
func qrysmExport(t *testing.T) (file, gvr string) {
	t.Helper()
	var idx struct {
		File string `json:"file"`
		GVR  string `json:"genesis_validators_root"`
	}
	vectors.Load(t, "interchange/index.json", &idx)
	return filepath.Join(vectors.Dir(), "interchange", idx.File), idx.GVR
}

// attestation is the golden mainnet-preset ATTESTATION request of interop key 0, with its epochs replaced when
// source and target are not empty (the signing root is then left out, so the signer computes it).
func attestation(t *testing.T, source, target string) (pubkey string, body []byte) {
	t.Helper()
	for _, c := range vectors.Signing(t) {
		if c.Preset != "mainnet" || c.Type != "ATTESTATION" || c.KeyIndex != 0 {
			continue
		}
		if source == "" {
			return c.Pubkey, c.RequestJSON
		}
		var req map[string]any
		if err := json.Unmarshal(c.RequestJSON, &req); err != nil {
			t.Fatal(err)
		}
		delete(req, "signing_root")
		att := req["attestation"].(map[string]any)
		att["source"].(map[string]any)["epoch"] = source
		att["target"].(map[string]any)["epoch"] = target
		b, err := json.Marshal(req)
		if err != nil {
			t.Fatal(err)
		}
		return c.Pubkey, b
	}
	t.Fatal("no mainnet ATTESTATION fixture for key 0")
	return "", nil
}

func (s *signer) sign(t *testing.T, pubkey string, body []byte) (int, string) {
	t.Helper()
	code, out := s.post("/api/v1/consensus/sign/"+pubkey, s.signToken(), body)
	if code != 200 {
		return code, reasonOf(t, out)
	}
	return code, ""
}

// The signer side of the migration runbook (docs/operations/migration.md) with the built binary: import qrysm's
// export, fence the store with a high watermark, start the signer and verify that the imported history and the
// fence hold, then lift the fence.
func TestMigrationRunbook(t *testing.T) {
	file, gvr := qrysmExport(t)
	keysDir, data := t.TempDir(), t.TempDir()
	writeInteropKeys(t, keysDir)
	store := "--data-path=" + data

	if code, out := runOffline(t, store, "consensus", "import", "--from="+file); code != 0 ||
		!strings.Contains(out, "imported 4 of 4 validator(s)") {
		t.Fatalf("import: %d %s", code, out)
	}
	if code, out := runOffline(t, store, "consensus", "set-high-watermark", "--epoch=40", "--slot=5120"); code != 0 {
		t.Fatalf("set-high-watermark: %d %s", code, out)
	}

	opts := options{keys: keysDir, data: data, noNetwork: true,
		consensus: []string{"--network=end-to-end-mainnet", "--network-genesis-validators-root=" + gvr}}
	s := start(t, opts)
	s.waitReady()
	if code, body, _ := s.do(request{path: "/api/v1/consensus/highWatermark", token: s.signToken()}); code != 200 ||
		body != `{"epoch":"40","slot":"5120"}` {
		t.Fatalf("highWatermark: %d %s", code, body)
	}
	pk, golden := attestation(t, "", "")
	// qrysm signed (9, 10) for key 0: the golden (8, 10) is a double vote.
	if code, reason := s.sign(t, pk, golden); code != 412 || reason != "SLASHING_DOUBLE_VOTE" {
		t.Fatalf("double vote against the imported history: %d %s", code, reason)
	}
	_, beyond := attestation(t, "12", "41")
	if code, reason := s.sign(t, pk, beyond); code != 412 || reason != "SLASHING_ABOVE_HIGH_WATERMARK" {
		t.Fatalf("attestation beyond the fence: %d %s", code, reason)
	}
	_, next := attestation(t, "12", "13")
	if code, reason := s.sign(t, pk, next); code != 200 {
		t.Fatalf("next attestation: %d %s", code, reason)
	}
	s.signal(syscall.SIGTERM)
	if code := s.exitCode(15 * time.Second); code != 0 {
		t.Fatalf("signer exit %d", code)
	}

	if code, out := runOffline(t, store, "consensus", "set-high-watermark", "--remove"); code != 0 {
		t.Fatalf("remove the fence: %d %s", code, out)
	}
	s = start(t, opts)
	s.waitReady()
	if code, body, _ := s.do(request{path: "/api/v1/consensus/highWatermark", token: s.signToken()}); code != 200 || body != `{}` {
		t.Fatalf("highWatermark after removal: %d %s", code, body)
	}
	if code, reason := s.sign(t, pk, beyond); code != 200 {
		t.Fatalf("attestation after the fence is lifted: %d %s", code, reason)
	}
	s.signal(syscall.SIGTERM)
	if code := s.exitCode(15 * time.Second); code != 0 {
		t.Fatalf("signer exit %d", code)
	}

	// The export carries the imported history and what the signer added.
	out := filepath.Join(t.TempDir(), "export.json")
	if code, msg := runOffline(t, store, "consensus", "export", "--to="+out); code != 0 {
		t.Fatalf("export: %d %s", code, msg)
	}
	exported, err := os.ReadFile(out)
	if err != nil {
		t.Fatal(err)
	}
	for _, want := range []string{`"genesis_validators_root": "` + gvr + `"`, `{"source_epoch": "12", "target_epoch": "41"`,
		`{"source_epoch": "9", "target_epoch": "10"`} {
		if !strings.Contains(string(exported), want) {
			t.Fatalf("the export lacks %s", want)
		}
	}
}

// The qrysm round trip with the built binary: consensus import of qrysm's export, consensus export, and
// vectorgen interchange-check, which imports the signer's export into a new qrysm validator database and requires
// qrysm's own export of it to equal the original. It builds tools/vectorgen, which links qrysm, so it runs only
// when REMOTESIGNER_VECTORS_VERIFY is set (make vectors-verify-binary).
func TestQrysmInterchangeRoundTrip(t *testing.T) {
	if os.Getenv("REMOTESIGNER_VECTORS_VERIFY") == "" {
		t.Skip("set REMOTESIGNER_VECTORS_VERIFY=1 to build tools/vectorgen and re-import the signer's export into qrysm")
	}
	file, _ := qrysmExport(t)
	store := "--data-path=" + t.TempDir()
	if code, out := runOffline(t, store, "consensus", "import", "--from="+file); code != 0 {
		t.Fatalf("import: %d %s", code, out)
	}
	export := filepath.Join(t.TempDir(), "signer-export.json")
	if code, out := runOffline(t, store, "consensus", "export", "--to="+export); code != 0 {
		t.Fatalf("export: %d %s", code, out)
	}
	check := exec.Command("go", "run", ".", "interchange-check", "-file", export)
	check.Dir = "../../tools/vectorgen"
	out, err := check.CombinedOutput()
	t.Logf("vectorgen interchange-check:\n%s", out)
	if err != nil {
		t.Fatalf("vectorgen interchange-check: %v", err)
	}
}
